/**
 * Indonesian address lookup for the pendaftaran form: kode pos -> kelurahan /
 * kecamatan / kota-kabupaten / provinsi, and a name search for parents who do
 * not know their kode pos. SERVER ONLY — the data is ~1.9 MB (560 KB gzipped)
 * and must never reach a client bundle; only the token-gated wilayah route
 * imports this module.
 *
 * Data: `data/wilayah.json`, generated by `scripts/vendor-wilayah.mjs` (see
 * its header and `data/NOTICE.txt` for sources and licences).
 *
 * Loading: a plain JSON import. The bundler inlines it into the one route's
 * server chunk, so there is no runtime file path to trace on Vercel (a
 * `readFileSync` of a repo file would need `outputFileTracingIncludes` and
 * fails silently in production when the key is wrong). It is parsed once per
 * server instance, the first time the route module loads. The cast below is
 * deliberate: it keeps the type small and explicit instead of inferred from
 * ten thousand JSON keys.
 */
import raw from "./data/wilayah.json";

export type WilayahEntry = {
  kodePos: string;
  kelurahan: string;
  kecamatan: string;
  kotaKab: string;
  provinsi: string;
};

type WilayahData = {
  v: number;
  p: string[];
  r: [string, number][];
  d: [string, number][];
  k: Record<string, [string, number][]>;
};

const data = raw as unknown as WilayahData;

const KODE_POS = /^\d{5}$/;

export const MIN_QUERY_LENGTH = 3;
export const MAX_QUERY_LENGTH = 60;
const MAX_TOKENS = 6;

function entryOf(kodePos: string, kelurahan: string, dIdx: number): WilayahEntry {
  const [kecamatan, rIdx] = data.d[dIdx];
  const [kotaKab, pIdx] = data.r[rIdx];
  return { kodePos, kelurahan, kecamatan, kotaKab, provinsi: data.p[pIdx] };
}

/**
 * Entries for an exact 5-digit kode pos, sorted by kelurahan name (then
 * kecamatan) so a dropdown reads alphabetically. Surrounding whitespace is
 * ignored; anything else that is not exactly five digits — short, long,
 * letters, non-string — returns [], as does a code nobody uses.
 */
export function lookupKodePos(code: string): WilayahEntry[] {
  if (typeof code !== "string") return [];
  const kodePos = code.trim();
  if (!KODE_POS.test(kodePos) || !Object.hasOwn(data.k, kodePos)) return [];
  return data.k[kodePos]
    .map(([kelurahan, dIdx]) => entryOf(kodePos, kelurahan, dIdx))
    .sort((a, b) => cmp(a.kelurahan, b.kelurahan) || cmp(a.kecamatan, b.kecamatan));
}

function cmp(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Lowercase, strip diacritics and punctuation, collapse whitespace. */
export function normalizeQuery(input: string): string {
  return input
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

// ---------------------------------------------------------------- search

type Index = {
  postal: string[]; // per row
  kel: string[]; // per row: raw kelurahan name
  dIdx: Uint16Array; // per row
  kelPad: string[]; // per row: " " + normalized kelurahan
  kecPad: string[]; // per district: " " + normalized kecamatan
  distPad: string[]; // per district: " " + normalized kecamatan + " " + kota/kab
};

let index: Index | null = null;

function buildIndex(): Index {
  const postal: string[] = [];
  const kel: string[] = [];
  const dIdxList: number[] = [];
  const kelPad: string[] = [];
  for (const [kodePos, rows] of Object.entries(data.k)) {
    for (const [name, dIdx] of rows) {
      postal.push(kodePos);
      kel.push(name);
      dIdxList.push(dIdx);
      kelPad.push(" " + normalizeQuery(name));
    }
  }
  const kecPad = data.d.map(([name]) => " " + normalizeQuery(name));
  const distPad = data.d.map(([, rIdx], i) => kecPad[i] + " " + normalizeQuery(data.r[rIdx][0]));
  return { postal, kel, dIdx: Uint16Array.from(dIdxList), kelPad, kecPad, distPad };
}

/**
 * Name search. The query is normalized (see `normalizeQuery`) and must be at
 * least 3 letters or digits (spaces do not count); every query word must be the start of some word in
 * "kelurahan kecamatan kota/kabupaten". Ranking, then data order (by kode pos,
 * then area code — deterministic):
 *   0  kelurahan name equals the query
 *   1  every query word starts a word of the kelurahan name
 *   2  every query word starts a word of the kecamatan name
 *   3  the words are spread over kelurahan / kecamatan / kota-kabupaten
 */
export function searchWilayah(query: string, limit = 20): WilayahEntry[] {
  if (typeof query !== "string" || !Number.isFinite(limit) || limit < 1) return [];
  const q = normalizeQuery(query.slice(0, MAX_QUERY_LENGTH * 2));
  if (q.length > MAX_QUERY_LENGTH || q.replace(/ /g, "").length < MIN_QUERY_LENGTH) return [];
  const tokens = q.split(" ").slice(0, MAX_TOKENS).map((t) => " " + t);
  const max = Math.floor(limit);

  const ix = (index ??= buildIndex());
  const exactPad = " " + q;
  const buckets: number[][] = [[], [], [], []];

  const startsAll = (hay: string) => {
    for (const t of tokens) if (!hay.includes(t)) return false;
    return true;
  };

  scan: for (let i = 0; i < ix.kel.length; i++) {
    const kelPad = ix.kelPad[i];
    const d = ix.dIdx[i];
    let tier: number;
    if (startsAll(kelPad)) {
      tier = kelPad === exactPad ? 0 : 1;
    } else if (startsAll(ix.kecPad[d])) {
      tier = 2;
    } else {
      const distPad = ix.distPad[d];
      let all = true;
      for (const t of tokens) {
        if (!kelPad.includes(t) && !distPad.includes(t)) {
          all = false;
          break;
        }
      }
      if (!all) continue;
      tier = 3;
    }
    const bucket = buckets[tier];
    if (bucket.length < max) bucket.push(i);
    // Nothing outranks a full set of best matches; stop scanning.
    if (tier === 0 && bucket.length >= max) break scan;
  }

  const out: WilayahEntry[] = [];
  for (const bucket of buckets) {
    for (const i of bucket) {
      if (out.length >= max) return out;
      out.push(entryOf(ix.postal[i], ix.kel[i], ix.dIdx[i]));
    }
  }
  return out;
}
